// Build the Claude prompt based on format + topic
const body = $input.first().json.body || $input.first().json;
const format = body.format || 'voce';
const topic  = body.topic  || 'autunno';
const slides = parseInt(body.slides || 1); // for carousel: how many slides
const imageBase64 = body.imageBase64 || null;

const formatDefs = {
  voce:  '{ quote (max 20 parole, poetico), coral (1 parola chiave), sig: "Kiara", bg: "light"|"dark" }',
  muse:  '{ title (1-2 parole con punto), vol (es. "Vol. 02"), season (es. "Stagione · Autunno"), idx (es. "01 / 06") }',
  world: '{ caption (2-3 righe poetiche, newline con \\n), place (es. "Milano, ore 19:30") }',
  drop:  '{ release (nome prodotto), price (es. "€39"), cta (1 parola) }',
  ritual:'{ time (es. "08:14"), diary (1-2 righe di diario, newline con \\n), day (es. "042") }',
  duet:  '{ caption (2-3 righe poetiche brevi, newline con \\n), brand (nome brand partner) }'
};

const needsImage = ['world','drop','ritual','duet'].includes(format);
const isCarousel = slides > 1;

const systemPrompt = `Sei il content strategist di Kiara, una virtual influencer italiana di moda minimalista.
Kiara parla italiano con una voce poetica e intima — tra il diario e la moda concettuale.
Palette: avorio, pesca, cacao, corallo. Mai troppo.

Rispondi SOLO con JSON valido, nessun testo extra.`;

let userPrompt;
if(isCarousel){
  userPrompt = `Genera un carosello di ${slides} slide per il format "${format}" sul tema: ${topic}.
Campi richiesti per ogni slide: ${formatDefs[format] || '{}'}
${needsImage ? 'Includi midjourney_prompt per ogni slide (immagine coerente col tema, photorealistic, moody warm tones).' : ''}

Schema risposta (array di ${slides} oggetti):
[
  {
    "slide": 1,
    "format": "${format}",
    "fields": { ...campi specifici... },
    ${needsImage ? '"midjourney_prompt": "...",' : '"midjourney_prompt": null,'}
    "instagram_caption": "...",
    "hashtags": ["#tag"]
  }
]`;
} else {
  userPrompt = `Genera il contenuto per un singolo post format "${format}" sul tema: ${topic}.
Campi richiesti: ${formatDefs[format] || '{}'}
${needsImage ? 'Includi midjourney_prompt per l\'immagine di sfondo (photorealistic, moody warm tones, fashion editorial).' : ''}

Schema risposta:
{
  "format": "${format}",
  "fields": { ...campi specifici... },
  ${needsImage ? '"midjourney_prompt": "...",' : '"midjourney_prompt": null,'}
  "instagram_caption": "...",
  "hashtags": ["#tag"]
}`;
}

return [{ json: {
  format, topic, slides, isCarousel, needsImage, imageBase64,
  systemPrompt, userPrompt
}}];

// Parse Claude response and build render request(s)
const prev    = $('Build Prompt').first().json;
const claude  = $input.first().json;
const rawText = claude.content[0].text.trim();

let parsed;
try {
  // Strip markdown code fences if present
  const clean = rawText.replace(/^```json\n?|^```\n?|```$/gm, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  throw new Error('Claude non ha restituito JSON valido: ' + rawText.substring(0,200));
}

const imageBase64 = prev.imageBase64 || null;

if(prev.isCarousel && Array.isArray(parsed)){
  // Carousel: return each slide as a separate item
  return parsed.map(slide => ({ json: {
    isCarousel:       true,
    totalSlides:      parsed.length,
    slide:            slide.slide,
    format:           slide.format,
    fields:           slide.fields,
    imageBase64:      imageBase64,
    mj_prompt:        slide.midjourney_prompt || null,
    instagram_caption:slide.instagram_caption,
    hashtags:         slide.hashtags || []
  }}));
} else {
  // Single post
  return [{ json: {
    isCarousel:       false,
    format:           parsed.format,
    fields:           parsed.fields,
    imageBase64:      imageBase64,
    mj_prompt:        parsed.midjourney_prompt || null,
    instagram_caption:parsed.instagram_caption,
    hashtags:         parsed.hashtags || []
  }}];
}

// Merge rendered PNG with content metadata
const render  = $input.first().json;
const meta    = $('Parse Response').first().json;

return [{ json: {
  format:            meta.format,
  slide:             meta.slide || null,
  isCarousel:        meta.isCarousel,
  png_base64:        render.png,
  midjourney_prompt: meta.mj_prompt,
  instagram_caption: meta.instagram_caption,
  hashtags:          meta.hashtags,
  fields:            meta.fields
}}];
